select count(1) from t_cruise_nonhomologous_warn_inspection a inner join t_cruise_nonhomologous_warn b on a.warn_id = b.warn_id
inner join t_cruise_nonhomologous_point_instance c on c.instance_id = b.instance_id
where a.task_id = #{taskId, jdbcType=VARCHAR} and a.inspection_id = #{instanceId, jdbcType=BIGINT} and c.instance_id = #{nonInstanceId, jdbcType=BIGINT}

select a.result_num as lastValue, a.task_id as taskId from u_patrol_data_result a where a.instance_id = #{instanceId} and result_num in
#{resultNum}
order by a.cruise_time desc limit 1

select inspection_id
from  t_robot_inspection
where inspection_code = #{deviceId, jdbcType=VARCHAR}
